import{_ as d,o,c as a,a2 as r}from"./chunks/framework.CqpfiAoK.js";const s=JSON.parse('{"title":"扩展设定建议清单","description":"","frontmatter":{},"headers":[],"relativePath":"zh/0098-扩展设定建议清单.md","filePath":"zh/0098-扩展设定建议清单.md"}'),h={name:"zh/0098-扩展设定建议清单.md"};function e(u,t,q,l,i,n){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="扩展设定建议清单" tabindex="-1">扩展设定建议清单 <a class="header-anchor" href="#扩展设定建议清单" aria-label="Permalink to &quot;扩展设定建议清单&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>文档编号</td><td>98</td></tr><tr><td>所属模块</td><td>附录与参考资料</td></tr><tr><td>核心关键词</td><td>扩展设定、创作建议、设定方向、开放性、待开发领域</td></tr></tbody></table><h2 id="一、说明" tabindex="-1">一、说明 <a class="header-anchor" href="#一、说明" aria-label="Permalink to &quot;一、说明&quot;">​</a></h2><p>本文档列出锚点共生文明设定体系中可供扩展创作的方向与建议，旨在为设定创作者提供灵感与指引，帮助其在已有框架内进行有价值的设定扩展。本清单按照模块分类，每个扩展方向包含方向描述、扩展价值、与已有设定的关联以及创作建议。需要强调的是，本清单仅为建议性参考，创作者可以在遵循设定一致性的前提下自由发挥，也可以开发本清单未涵盖的全新方向。所有扩展设定须通过文档97《设定矛盾自查表》的检查后方可正式纳入。</p><h2 id="二、世界观与核心设定扩展方向" tabindex="-1">二、世界观与核心设定扩展方向 <a class="header-anchor" href="#二、世界观与核心设定扩展方向" aria-label="Permalink to &quot;二、世界观与核心设定扩展方向&quot;">​</a></h2><table tabindex="0"><thead><tr><th>编号</th><th>扩展方向</th><th>扩展价值</th><th>关联设定</th><th>创作建议</th></tr></thead><tbody><tr><td>E01</td><td>宇宙边界之外的存在</td><td>探索衡元宙法则网络之外是否存在其他宇宙或更高维度存在，为设定提供更宏大的宇宙观</td><td>文档00、文档28</td><td>可以设定&quot;宇宙壁&quot;的存在，以及极少数突破宇宙壁的探索者的故事，为后续跨宇宙交互埋下伏笔</td></tr><tr><td>E02</td><td>宇宙意志的本质</td><td>深入探讨法则网络底层是否存在某种&quot;宇宙意志&quot;，以及它与锚点机制的关系</td><td>文档00、文档20</td><td>可以将宇宙意志设定为一种非人格化的法则自组织现象，而非某个具体的神祇，保持&quot;现实为基&quot;的立场</td></tr><tr><td>E03</td><td>前锚点时代的失落文明</td><td>详细设定前锚点时代中曾经辉煌但已消亡的文明，丰富历史深度</td><td>文档71、文档93</td><td>可以设定3-5个具有代表性的失落文明，每个文明有其独特的修炼体系、文化与消亡原因，为考古设定提供素材</td></tr><tr><td>E04</td><td>共生理念的哲学流派</td><td>在&quot;反掠夺、倡共生&quot;的大框架下，设定不同的哲学流派对共生理念的不同诠释</td><td>文档04、文档03</td><td>可以设定&quot;激进共生派&quot;&quot;温和共生派&quot;&quot;生态共生派&quot;&quot;技术共生派&quot;等流派，它们之间的思想交锋可以成为重要的剧情张力</td></tr></tbody></table><h2 id="三、修炼体系扩展方向" tabindex="-1">三、修炼体系扩展方向 <a class="header-anchor" href="#三、修炼体系扩展方向" aria-label="Permalink to &quot;三、修炼体系扩展方向&quot;">​</a></h2><table tabindex="0"><thead><tr><th>编号</th><th>扩展方向</th><th>扩展价值</th><th>关联设定</th><th>创作建议</th></tr></thead><tbody><tr><td>E05</td><td>单套体系的详细法门</td><td>对三百套体系中的某一套进行详细展开，包括具体修炼法门、境界突破方法、常见误区等</td><td>文档10-19、文档91</td><td>建议优先展开本源三基以及应用工程类中与技术结合紧密的体系，每套体系的详细文档可包含修炼步骤、心法口诀、资源需求、风险提示等</td></tr><tr><td>E06</td><td>体系兼修的组合方案</td><td>研究不同体系之间的兼修兼容性，设计最优的多体系组合方案</td><td>文档10、文档11-13</td><td>可以设定&quot;黄金组合&quot;（如推演迭代+空间法理+应用工程）以及各种偏门组合，分析每种组合的优势与局限</td></tr><tr><td>E07</td><td>修炼瓶颈与突破方法</td><td>详细设定各体系在不同境界可能遇到的瓶颈，以及突破瓶颈的多种方法</td><td>文档14、文档19</td><td>可以设定&quot;心魔劫&quot;&quot;法则关&quot;&quot;本源障&quot;等不同类型的瓶颈，以及对应的突破路径，增加修炼过程的层次感</td></tr><tr><td>E08</td><td>特殊体质与体系适配</td><td>设定各种特殊体质（如先天道体、元素亲和体、意识强感器等）及其与不同修炼体系的适配关系</td><td>文档12、文档51</td><td>可以设计一个&quot;体质-体系适配矩阵&quot;，帮助创作者快速判断某种体质适合修炼哪些体系</td></tr><tr><td>E09</td><td>修炼资源的详细分类</td><td>对修炼所需的各种资源（天材地宝、能量晶体、法则碎片等）进行详细分类与设定</td><td>文档18、文档65</td><td>可以设定资源的品级、产地、采集方法、保存方式、使用禁忌等，构建完整的修炼资源生态</td></tr></tbody></table><h2 id="四、社会制度扩展方向" tabindex="-1">四、社会制度扩展方向 <a class="header-anchor" href="#四、社会制度扩展方向" aria-label="Permalink to &quot;四、社会制度扩展方向&quot;">​</a></h2><table tabindex="0"><thead><tr><th>编号</th><th>扩展方向</th><th>扩展价值</th><th>关联设定</th><th>创作建议</th></tr></thead><tbody><tr><td>E10</td><td>五种分型的具体社会形态</td><td>对五种共生文明分型各自的具体社会制度、经济模式、文化特征进行详细展开</td><td>文档30-35</td><td>每种分型可以设定其典型的城市形态、家庭结构、教育模式、节日庆典等，使五种分型各具特色</td></tr><tr><td>E11</td><td>共生城市的规划与建设</td><td>设定共生文明中城市的规划理念、建筑风格、基础设施、功能分区</td><td>文档39、文档60</td><td>可以设计&quot;垂直共生城市&quot;&quot;生态嵌套城市&quot;&quot;空间折叠城市&quot;等不同类型的城市形态</td></tr><tr><td>E12</td><td>教育体系的详细运作</td><td>详细设定共生教育体系从学前教育到高等教育、修炼教育的完整运作机制</td><td>文档37、文档43</td><td>可以设定课程体系、考核方式、导师制度、跨种族教育方案等</td></tr><tr><td>E13</td><td>医疗体系的详细运作</td><td>详细设定共生医疗体系的运作机制，包括常规医疗与修炼医疗的结合</td><td>文档38、文档44</td><td>可以设定医院体系、医保报销流程、修炼治疗的特殊规范、跨种族医疗方案等</td></tr><tr><td>E14</td><td>社会保障与福利体系</td><td>详细设定共生文明的社会保障体系，包括养老、失业、救助等</td><td>文档32、文档08</td><td>可以设定福利的申领条件、发放标准、资金来源、监督机制等</td></tr></tbody></table><h2 id="五、法律与治理扩展方向" tabindex="-1">五、法律与治理扩展方向 <a class="header-anchor" href="#五、法律与治理扩展方向" aria-label="Permalink to &quot;五、法律与治理扩展方向&quot;">​</a></h2><table tabindex="0"><thead><tr><th>编号</th><th>扩展方向</th><th>扩展价值</th><th>关联设定</th><th>创作建议</th></tr></thead><tbody><tr><td>E15</td><td>典型法律案例</td><td>编写共生法院审理的典型案例，展示法律在实际中的应用</td><td>文档40-49、文档92</td><td>可以编写&quot;修炼资源垄断案&quot;&quot;跨位面污染赔偿案&quot;&quot;黑暗置换体权利案&quot;等具有代表性的案例</td></tr><tr><td>E16</td><td>地方自治制度</td><td>详细设定各星域、各位面在宪法框架内的自治制度与权限划分</td><td>文档40、文档49</td><td>可以设定不同自治单位的自治模式、与中央政府的关系、自治条例的制定程序等</td></tr><tr><td>E17</td><td>选举与民主制度</td><td>详细设定锚点议事会代表的选举制度与民主决策机制</td><td>文档32、文档49</td><td>可以设定选区划分、候选人资格、选举程序、投票方式、任期制度等</td></tr><tr><td>E18</td><td>法律执行机制</td><td>详细设定法律的执行机制，包括执法机构、执行程序、强制措施</td><td>文档48、文档49</td><td>可以设定执法机构的组织架构、执法权限、执法程序、监督机制等</td></tr></tbody></table><h2 id="六、生命与种族扩展方向" tabindex="-1">六、生命与种族扩展方向 <a class="header-anchor" href="#六、生命与种族扩展方向" aria-label="Permalink to &quot;六、生命与种族扩展方向&quot;">​</a></h2><table tabindex="0"><thead><tr><th>编号</th><th>扩展方向</th><th>扩展价值</th><th>关联设定</th><th>创作建议</th></tr></thead><tbody><tr><td>E19</td><td>单个种族的详细设定</td><td>对万族名录中的某个种族进行详细展开，包括生理特征、社会结构、文化传统、历史演变</td><td>文档50-52、文档94</td><td>建议优先展开龙族、精灵族、机械族、意识体族等具有特色的种族，每个种族可包含语言、宗教、艺术、习俗等</td></tr><tr><td>E20</td><td>奇特生命的具体案例</td><td>设定具体的奇特生命个体或族群，展示三类处置流程的实际应用</td><td>文档53-54</td><td>可以设定&quot;虚空漂流者&quot;&quot;时间碎片生命&quot;&quot;法则寄生体&quot;等奇特生命案例</td></tr><tr><td>E21</td><td>奇异能量的具体类型</td><td>详细设定各种奇异能量的特性、来源、用途与管控方法</td><td>文档55-56</td><td>可以设定&quot;因果能量&quot;&quot;意识能量&quot;&quot;时间残响能量&quot;等奇异能量类型</td></tr><tr><td>E22</td><td>黑暗置换体的具体案例</td><td>设定具体的黑暗置换体个体故事，展示双魂伦理与四类分支处置的实际应用</td><td>文档57-59</td><td>可以编写不同类型黑暗置换体的案例故事，探讨双魂共存的伦理困境</td></tr><tr><td>E23</td><td>跨种族融合的后代</td><td>设定不同种族通婚产生的混合种族的特征与文化</td><td>文档52、文档77</td><td>可以设定&quot;半精灵&quot;&quot;龙人&quot;&quot;机械生化人&quot;等混合种族，探讨其身份认同与文化融合</td></tr></tbody></table><h2 id="七、技术与能量扩展方向" tabindex="-1">七、技术与能量扩展方向 <a class="header-anchor" href="#七、技术与能量扩展方向" aria-label="Permalink to &quot;七、技术与能量扩展方向&quot;">​</a></h2><table tabindex="0"><thead><tr><th>编号</th><th>扩展方向</th><th>扩展价值</th><th>关联设定</th><th>创作建议</th></tr></thead><tbody><tr><td>E24</td><td>单项技术的详细原理</td><td>对某项关键技术（如复制镜、隔离空间、倍增果实工程化）进行详细的原理解析</td><td>文档60-69、文档63-64</td><td>可以设定技术的发展历程、核心组件、工作流程、技术局限、升级方向等</td></tr><tr><td>E25</td><td>修炼器械的详细分类</td><td>设定各种修炼辅助器械的分类、功能、品级与使用方法</td><td>文档61、文档67</td><td>可以设定&quot;修炼舱&quot;&quot;法则检测仪&quot;&quot;能量转换器&quot;&quot;意识增幅器&quot;等器械类型</td></tr><tr><td>E26</td><td>锚点硬件的详细设定</td><td>详细设定锚点硬件设施的结构、功能、建设与维护</td><td>文档20、文档67</td><td>可以设定人工锚点的核心组件、能量供应、维护周期、故障处理等</td></tr><tr><td>E27</td><td>跨位面通讯技术</td><td>详细设定跨位面通讯的技术原理、设备类型、通讯协议与安全机制</td><td>文档66、文档81</td><td>可以设定&quot;锚点波通讯&quot;&quot;空间折叠通讯&quot;&quot;意识共振通讯&quot;等不同通讯方式</td></tr></tbody></table><h2 id="八、历史与事件扩展方向" tabindex="-1">八、历史与事件扩展方向 <a class="header-anchor" href="#八、历史与事件扩展方向" aria-label="Permalink to &quot;八、历史与事件扩展方向&quot;">​</a></h2><table tabindex="0"><thead><tr><th>编号</th><th>扩展方向</th><th>扩展价值</th><th>关联设定</th><th>创作建议</th></tr></thead><tbody><tr><td>E28</td><td>重大历史事件的详细记述</td><td>对编年史中的某个重大事件进行详细的历史记述</td><td>文档70-79、文档93</td><td>可以详细记述&quot;三百套体系开放事件&quot;&quot;20%激活战略实施&quot;&quot;首次升维里程碑&quot;等事件的全过程</td></tr><tr><td>E29</td><td>历史人物的传记</td><td>为关键人物撰写详细的传记，丰富历史的人文厚度</td><td>文档95</td><td>可以为&quot;玄衡子&quot;&quot;共生子&quot;&quot;立宪公&quot;&quot;三百师&quot;等关键人物撰写传记</td></tr><tr><td>E30</td><td>历史转折点的假设分析</td><td>分析如果某个历史事件走向不同，共生文明的发展会有何不同</td><td>文档70-79</td><td>可以做&quot;如果共生宪法未通过&quot;&quot;如果20%激活战略失败&quot;等假设分析，展示历史的偶然性</td></tr><tr><td>E31</td><td>考古发现的详细记录</td><td>设定某次跨位面考古的详细发现与研究成果</td><td>文档84-87</td><td>可以设定&quot;某失落文明的考古发现&quot;&quot;某关键历史节点的时间回溯考古成果&quot;等</td></tr></tbody></table><h2 id="九、跨位面与时间扩展方向" tabindex="-1">九、跨位面与时间扩展方向 <a class="header-anchor" href="#九、跨位面与时间扩展方向" aria-label="Permalink to &quot;九、跨位面与时间扩展方向&quot;">​</a></h2><table tabindex="0"><thead><tr><th>编号</th><th>扩展方向</th><th>扩展价值</th><th>关联设定</th><th>创作建议</th></tr></thead><tbody><tr><td>E32</td><td>具体位面的详细设定</td><td>设定某个具体位面的法则参数、文明形态、地理环境与历史</td><td>文档80、文档81</td><td>可以设定&quot;高魔位面&quot;&quot;科技位面&quot;&quot;蛮荒位面&quot;&quot;意识位面&quot;等不同类型的具体位面</td></tr><tr><td>E33</td><td>跨位面外交案例</td><td>设定共生文明与其他位面文明建立外交关系的具体案例</td><td>文档81、文档88</td><td>可以设定首次接触、建交谈判、文化交流、贸易协定等具体外交事件</td></tr><tr><td>E34</td><td>时间回溯的具体案例</td><td>设定某次时间回溯操作的具体过程、发现与影响</td><td>文档82-83、文档89</td><td>可以设定&quot;某历史谜团的回溯破解&quot;&quot;某灭绝文明的回溯复原&quot;等案例</td></tr><tr><td>E35</td><td>时间悖论事件的详细记录</td><td>设定某次时间悖论事件的发生、应急响应与因果修复全过程</td><td>文档89</td><td>可以编写一次小规模悖论事件的完整处置记录，展示防控机制的实际运作</td></tr><tr><td>E36</td><td>跨位面冲突与解决</td><td>设定共生文明与其他位面文明之间的冲突及其和平解决过程</td><td>文档81、文档88</td><td>可以设定资源争端、文化冲突、边界纠纷等不同类型的跨位面冲突案例</td></tr></tbody></table><h2 id="十、扩展设定的创作原则" tabindex="-1">十、扩展设定的创作原则 <a class="header-anchor" href="#十、扩展设定的创作原则" aria-label="Permalink to &quot;十、扩展设定的创作原则&quot;">​</a></h2><p>在进行扩展设定创作时，应遵循以下原则：</p><ol><li><strong>一致性优先</strong>：所有扩展设定必须与已有设定保持逻辑一致，通过设定矛盾自查表的检查。</li><li><strong>现实为基</strong>：扩展设定应基于客观规律进行合理推演，避免纯粹的空想与设定崩坏。</li><li><strong>共生立场</strong>：扩展设定应始终坚持反掠夺、倡共生的核心立场，不得为掠夺式行为辩护。</li><li><strong>开放性</strong>：扩展设定应保持一定的开放性，为后续的进一步扩展预留空间。</li><li><strong>实用性</strong>：扩展设定应具有实际的创作价值，能够为故事创作、游戏设计、理论探讨提供有用的素材。</li></ol><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>扩展设定建议清单是锚点共生文明设定体系的&quot;开放之门&quot;。它表明这个设定体系不是一个封闭的、完成态的产品，而是一个持续生长、不断丰富的活的体系。三十六个扩展方向只是起点，真正的设定创造力来源于每一位参与者的想象力与热情。只要遵循设定一致性的基本原则，每一个有价值的扩展都将成为锚点共生文明宏大叙事中不可或缺的组成部分。</p><h2 id="关联文档" tabindex="-1">关联文档 <a class="header-anchor" href="#关联文档" aria-label="Permalink to &quot;关联文档&quot;">​</a></h2><ul><li>0097-设定矛盾自查表</li><li>0099-文档版本与维护说明</li><li>0096-常见问题FAQ</li></ul>',27)])])}const c=d(h,[["render",e]]);export{s as __pageData,c as default};
